-- DINO COACH — 0006: bảng mẫu giáo án + 3 mẫu khởi đầu. Chạy SAU 0001–0004 và SAU khi đã set role coach. Status: PROPOSED
-- payload: tuần 1 soạn tay; "Sinh các tuần còn lại" (DINO-009) dùng formulas.generateWeek, tuần cuối deload.
-- Bài tham chiếu bằng name_vi → khi áp mẫu, app tra exercises.name_vi lấy id.
create table if not exists public.program_templates (
  id uuid primary key default gen_random_uuid(),
  coach_id uuid not null references public.profiles(id) on delete cascade,
  name text not null, goal text, model text, weeks int,
  payload jsonb not null,
  created_at timestamptz not null default now(),
  unique (coach_id, name)
);
alter table public.program_templates enable row level security;
create policy program_templates_coach on public.program_templates for all to authenticated
  using (coach_id = (select auth.uid())) with check (coach_id = (select auth.uid()));

